//! Exact Z3 5.1.0 command-line parameter discovery.
//!
//! Mechanically captured from `/opt/homebrew/bin/z3` (`Z3 version 5.1.0 - 64
//! bit`, SHA-256
//! `8b61a8bc0b7a4e14dfb119910502ef808b055df636b25c8b67b96ae630fbc29c`)
//! and authenticated against the pinned Z3 source tree at commit
//! `0b6cdcdbc65da25ef0f73ac9da210574d0f66cf8`. The closed database contains
//! all 25 global parameters and 663 parameters across all 22 registered
//! modules. Repeated output lines are interned and output profiles store u16
//! indices so the byte-exact catalog remains compact.
//!
//! Z3 5.0.0 dereferenced a null default string and crashed for the parameters
//! with no default value when queried through `-pp`; AY rendered the complete
//! record with an empty default instead. Z3 5.1.0 does the same as AY: it
//! prints the record with an empty default and exits cleanly, so the oracle
//! and AY now agree byte-for-byte. `NULL_DEFAULT_PARAMETERS` pins the 15
//! parameters whose default value is empty.

