pub(crate) fn print_request(request: &str) -> i32 {
    if request == "-p" || request.starts_with("-p:") {
        print_profile(ALL_PARAMETERS);
        return 0;
    }
    if request == "-pd" || request.starts_with("-pd:") {
        print_profile(ALL_PARAMETER_DESCRIPTIONS);
        return 0;
    }
    if request == "-pm" || request == "-pmmd" {
        print_profile(MODULE_LIST);
        return 0;
    }
    if let Some(module) = request.strip_prefix("-pm:") {
        return print_module(MODULE_TEXT, module);
    }
    if let Some(module) = request.strip_prefix("-pmmd:") {
        return print_module(MODULE_MARKDOWN, module);
    }
    if request == "-pp" {
        safe_eprintln!("Error: option argument (-pp:name) is missing.");
        safe_eprintln!("For usage information: z3 -h");
        return 109;
    }
    if let Some(name) = request.strip_prefix("-pp:") {
        return print_parameter(name);
    }
    safe_eprintln!("Error: invalid command line option: {request}");
    safe_eprintln!("For usage information: z3 -h");
    109
}

pub(crate) fn print_z3_help() {
    safe_print!("{}", Z3_HELP);
}

pub(crate) fn print_z3_version() {
    safe_println!("Z3 version 5.1.0 - 64 bit");
}

pub(crate) fn print_missing_verbosity_error() {
    safe_eprintln!("Error: option argument (-v:level) is missing.");
    safe_eprintln!("For usage information: z3 -h");
}

fn print_module(entries: &[(&str, u16)], module: &str) -> i32 {
    if let Some(profile) = lookup(entries, module) {
        print_profile(profile);
        0
    } else {
        safe_eprintln!("ERROR: unknown module '{module}'");
        110
    }
}

fn print_parameter(original: &str) -> i32 {
    let (module, parameter) = normalize_parameter(original);
    safe_println!("{original} {module} {parameter}");

    let key = if module.is_empty() {
        parameter.clone()
    } else {
        format!("{module}.{parameter}")
    };
    if let Some(profile) = lookup(PARAMETER_DETAILS, &key) {
        print_profile(profile);
        return 0;
    }

    if !module.is_empty() {
        let Some(legal) = lookup(MODULE_LEGAL_PARAMETERS, &module) else {
            safe_eprintln!("ERROR: unknown module '{module}'");
            return 110;
        };
        safe_eprintln!("ERROR: unknown parameter '{parameter}' at module '{module}'");
        safe_eprintln!("Legal parameters are:");
        // Description-free, and closed by a blank line -- same shape as the
        // `(set-option :mod.bad …)` error body. `-pm:<module>` keeps the prose.
        for line in OUTPUT_PROFILES[legal as usize] {
            safe_eprintln!(
                "{}",
                strip_parameter_description(OUTPUT_LINES[*line as usize])
            );
        }
        safe_eprintln!();
        return 110;
    }

    if let Some((_, replacement)) = RENAMED_GLOBAL_PARAMETERS
        .iter()
        .find(|(candidate, _)| *candidate == parameter)
    {
        safe_eprintln!(
            "ERROR: the parameter '{parameter}', invoke 'z3 -p' to obtain the new parameter list, and 'z3 -pp:{replacement}' for the full description of the parameter"
        );
        return 110;
    }
    if OLD_GLOBAL_PARAMETERS
        .binary_search(&parameter.as_str())
        .is_ok()
    {
        safe_eprintln!(
            "ERROR: unknown parameter '{parameter}', this is an old parameter name, invoke 'z3 -p' to obtain the new parameter list"
        );
        return 110;
    }

    safe_eprintln!("ERROR: unknown parameter '{parameter}'");
    safe_eprintln!("Legal parameters are:");
    eprint_profile(GLOBAL_LEGAL_PARAMETERS);
    // z3 closes the legal list with a blank line before the trailing
    // `<key> <module> <parameter>` line it writes to stdout.
    safe_eprintln!();
    110
}

fn normalize_parameter(name: &str) -> (String, String) {
    let name = name.strip_prefix(':').unwrap_or(name);
    let normalized = name
        .chars()
        .map(|ch| match ch {
            'A'..='Z' => ch.to_ascii_lowercase(),
            '-' => '_',
            _ => ch,
        })
        .collect::<String>();
    if let Some((module, parameter)) = normalized.split_once('.') {
        (module.to_string(), parameter.to_string())
    } else {
        (String::new(), normalized)
    }
}

fn lookup(entries: &[(&str, u16)], name: &str) -> Option<u16> {
    entries
        .binary_search_by_key(&name, |(candidate, _)| *candidate)
        .ok()
        .map(|index| entries[index].1)
}

fn print_profile(profile: u16) {
    for line in OUTPUT_PROFILES[profile as usize] {
        safe_println!("{}", OUTPUT_LINES[*line as usize]);
    }
}

fn eprint_profile(profile: u16) {
    for line in OUTPUT_PROFILES[profile as usize] {
        safe_eprintln!("{}", OUTPUT_LINES[*line as usize]);
    }
}

const Z3_HELP: &str = "Z3 [version 5.1.0 - 64 bit]. (C) Copyright 2006-2016 Microsoft Corp.\nUsage: z3 [options] [-file:]file\n\nInput format:\n  -smt2       use parser for SMT 2 input format.\n  -dl         use parser for Datalog input format.\n  -dimacs     use parser for DIMACS input format.\n  -wcnf       use parser for Weighted CNF DIMACS input format.\n  -opb        use parser for PB optimization input format.\n  -lp         use parser for a modest subset of CPLEX LP input format.\n  -log        use parser for Z3 log input format.\n  -tptp       use parser for TPTP input format (fof/cnf/tff/thf fragments).\n  -in         read formula from standard input.\n  -model      display model for satisfiable SMT.\n\nMiscellaneous:\n  -h, -?      prints this message.\n  -version    prints version number of Z3.\n  -v:level    be verbose, where <level> is the verbosity level.\n  -nw         disable warning messages.\n  -p          display Z3 global (and module) parameters.\n  -pd         display Z3 global (and module) parameter descriptions.\n  -pm:name    display Z3 module ('name') parameters.\n  -pmmd:name  display Z3 module ('name') parameters in Markdown format.\n  -pp:name    display Z3 parameter description, if 'name' is not provided, then all module names are listed.\n  -tactics[:name]  display built-in tactics or if argument is given, display detailed information on tactic.\n  -simplifiers[:name]  display built-in simplifiers or if argument is given, display detailed information on simplifier.\n  -probes     display avilable probes.\n  --          all remaining arguments are assumed to be part of the input file name. This option allows Z3 to read files with strange names such as: -foo.smt2.\n\nResources:\n  -T:timeout  set the timeout (in seconds).\n  -t:timeout  set the soft timeout (in milli seconds). It only kills the current query.\n  -memory:Megabytes  set a limit for virtual memory consumption.\n\nOutput:\n  -st         display statistics.\n\nParameter setting:\nGlobal and module parameters can be set in the command line.\n  param_name=value              for setting global parameters.\n  module_name.param_name=value  for setting module parameters.\nUse 'z3 -p' for the complete list of global and module parameters.\n";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_z3_510_parameter_database_is_closed() {
        let globals = PARAMETER_DETAILS
            .iter()
            .filter(|(name, _)| !name.contains('.'))
            .count();
        assert_eq!(globals, 25);
        assert_eq!(MODULE_TEXT.len(), 22);
        assert_eq!(MODULE_MARKDOWN.len(), 23);
        assert_eq!(PARAMETER_DETAILS.len(), 688);
        assert_eq!(PARAMETER_DETAILS.len() - globals, 663);
        assert_eq!(NULL_DEFAULT_PARAMETERS.len(), 15);
    }

    #[test]
    fn maps_are_sorted_and_profiles_are_in_bounds() {
        for entries in [
            MODULE_TEXT,
            MODULE_MARKDOWN,
            MODULE_LEGAL_PARAMETERS,
            PARAMETER_DETAILS,
        ] {
            assert!(entries.windows(2).all(|pair| pair[0].0 < pair[1].0));
            assert!(entries
                .iter()
                .all(|(_, profile)| (*profile as usize) < OUTPUT_PROFILES.len()));
        }
        assert!(OUTPUT_PROFILES
            .iter()
            // `OUTPUT_PROFILES` is `&[&[u16]]`, so `.iter()` yields
            // `&&[u16]` — a double reference, which is not
            // `IntoIterator`, so `.flatten()` does not compile.
            .copied()
            .flatten()
            .all(|line| (*line as usize) < OUTPUT_LINES.len()));
        assert!(OLD_GLOBAL_PARAMETERS
            .windows(2)
            .all(|pair| pair[0] < pair[1]));
    }

    #[test]
    fn z3_parameter_normalization_matches_source() {
        assert_eq!(
            normalize_parameter(":SMT.RANDOM-SEED"),
            ("smt".to_string(), "random_seed".to_string())
        );
        assert_eq!(
            normalize_parameter("well-sorted-check"),
            (String::new(), "well_sorted_check".to_string())
        );
    }
}

/// The exact `Legal parameters are:` block z3 5.1.0 prints when `set-option`
/// names a parameter it does not recognize.
///
/// Same pinned data the `-p` request profile uses, so the error body cannot
/// drift from the help output.
pub(crate) fn legal_global_parameter_lines() -> impl Iterator<Item = &'static str> {
    OUTPUT_PROFILES[GLOBAL_LEGAL_PARAMETERS as usize]
        .iter()
        .map(|index| OUTPUT_LINES[*index as usize])
}

/// Whether `name` is one of the 25 global parameters z3 5.1.0 recognizes.
///
/// Derived from the same pinned table rather than a hand-kept duplicate list —
/// a name is legal exactly when it heads one of the lines z3 would print.
pub(crate) fn is_known_global_parameter(name: &str) -> bool {
    legal_global_parameter_lines()
        .filter_map(|line| line.split_whitespace().next())
        .any(|parameter| parameter == name)
}

/// Whether `module` is one of the 22 parameter modules z3 5.1.0 exposes.
///
/// `module` must already be normalized (`-` -> `_`, lowercased) the way z3
/// normalizes it before the lookup.
pub(crate) fn is_known_module(module: &str) -> bool {
    MODULE_LEGAL_PARAMETERS
        .iter()
        .any(|(name, _)| *name == module)
}

/// The legal-parameter lines z3 prints when rejecting a parameter in `module`.
///
/// Same pinned profile the `-pm:<module>` request uses, so an error body cannot
/// drift from the help output. `None` when the module is unknown.
pub(crate) fn legal_module_parameter_lines(
    module: &str,
) -> Option<impl Iterator<Item = &'static str>> {
    let profile = MODULE_LEGAL_PARAMETERS
        .iter()
        .find(|(name, _)| *name == module)?
        .1;
    Some(
        OUTPUT_PROFILES[profile as usize]
            .iter()
            .map(|index| OUTPUT_LINES[*index as usize]),
    )
}

/// Whether `module` declares a parameter named `name`. Both must already be
/// normalized. Derived from the same pinned table as the help output.
pub(crate) fn is_known_module_parameter(module: &str, name: &str) -> bool {
    legal_module_parameter_lines(module)
        .is_some_and(|mut lines| lines.any(|line| line.split_whitespace().next() == Some(name)))
}

/// Drop the prose description from a `-pm` parameter line.
///
/// z3's help output carries a description that its ERROR body does not:
///
///   help:  `  elim_01 (bool) eliminate 01 variables (default: true)`
///   error: `  elim_01 (bool) (default: true)`
///
/// Keeps `name (type)` and re-appends the trailing default. The default is
/// located with `rfind`, because a description may itself contain parenthesized
/// text -- `string_solver`'s lists five alternatives in parentheses before its
/// real `(default: seq)`. Two of `smt`'s 156 parameters (`logic`, `mbqi.id`)
/// have no default at all and keep just `name (type)`.
fn strip_parameter_description(line: &str) -> String {
    const DEFAULT_MARKER: &str = " (default: ";

    let Some(type_open) = line.find('(') else {
        return line.to_string();
    };
    let Some(offset) = line[type_open..].find(')') else {
        return line.to_string();
    };
    let type_end = type_open + offset + 1;

    match line.rfind(DEFAULT_MARKER) {
        Some(idx) if idx >= type_end => format!("{}{}", &line[..type_end], &line[idx..]),
        _ => line[..type_end].to_string(),
    }
}

/// The legal-parameter lines exactly as z3 prints them inside a module error
/// body -- i.e. [`legal_module_parameter_lines`] without the descriptions.
pub(crate) fn legal_module_parameter_report_lines(
    module: &str,
) -> Option<impl Iterator<Item = String>> {
    Some(legal_module_parameter_lines(module)?.map(strip_parameter_description))
}
